// spec: .qa/e2e/specs/admin.md (24.1–24.3)
// seed: tests/seed.spec.ts, tests/seed.user1.spec.ts, tests/seed.admin.spec.ts
// ПРОД: только просмотр. «יציאה מהחשבון» не нажимать — выход отзывает сессию в .qa/auth/<role>.json.
import { test, expect } from '../../fixtures';

const DAILY: Array<[string, number]> = [
  ['שחרית', 66],
  ['שחרית', 57],
  ['מנחה', 8],
  ['מנחה', 11],
  ['ערבית', 15],
  ['ערבית', 16],
];
const NUSACH = ['אשכנז', 'ספרד', 'אשכנז', 'ספרד', 'אשכנז', 'ספרד'];

test.describe('Админка контента молитв (/admin)', () => {
  test('AD-01 /admin: гость — экран входа, без содержимого админки #a5decf4a @prod-safe @mobile', async ({ asUser }) => {
    const guest = await asUser('guest');
    // 1. Открыть /admin без сессии.
    await guest.goto('/admin');
    await expect(guest.getByRole('textbox').first()).toBeVisible({ timeout: 20_000 });
    await expect(guest.getByText('ניהול תכני תפילה')).toHaveCount(0);
    await expect(guest.getByText('תפילות היום', { exact: true })).toHaveCount(0);
    await expect(guest.getByText(/קטעים מאושרים/)).toHaveCount(0);
  });

  test('AD-01 /admin: user1 — «לחשבון הזה אין גישה לממשק הניהול» #a5decf4a @prod-safe @mobile', async ({ asUser }) => {
    const user = await asUser('user1');
    // 1. Открыть /admin под user1. «יציאה מהחשבון» НЕ нажимать.
    await user.goto('/admin');
    await expect(user.getByText('לחשבון הזה אין גישה לממשק הניהול')).toBeVisible({ timeout: 20_000 });
    await expect(user.getByRole('button', { name: 'יציאה מהחשבון' })).toBeVisible();
    await expect(user.getByText('ניהול תכני תפילה')).toHaveCount(0);
    await expect(user.getByText('תפילות היום', { exact: true })).toHaveCount(0);
  });

  test('AD-01/AD-03 /admin: admin — список молитв со счётчиками «N מתוך M קטעים מאושרים» #a5decf4a @prod-safe @mobile', async ({ asUser }) => {
    const admin = await asUser('admin');
    // 1. Открыть /admin под admin.
    await admin.goto('/admin');
    await expect(admin.getByText('ניהול תכני תפילה')).toBeVisible({ timeout: 20_000 });
    await expect(admin.getByText(/^שלום, /)).toBeVisible();
    await expect(admin.getByText('תפילות היום', { exact: true })).toBeVisible();
    await expect(admin.getByText('תפילות ומקטעים לזמנים מיוחדים', { exact: true })).toBeVisible();

    // Карточки «<молитва> · נוסח <נוסח>» и под каждой «N מתוך M קטעים מאושרים».
    await expect(admin.getByText(/מתוך 16 קטעים מאושרים/).first()).toBeVisible();
    const body = await admin.locator('body').innerText();
    for (let i = 0; i < DAILY.length; i++) {
      const [prayer, total] = DAILY[i];
      const re = new RegExp(`${prayer}\\s*.\\s*נוסח ${NUSACH[i]}\\s*\\n+\\s*(\\d+) מתוך ${total} קטעים מאושרים`);
      const m = body.match(re);
      expect(m, `карточка «${prayer} · נוסח ${NUSACH[i]}» со счётчиком «N מתוך ${total} קטעים מאושרים»`).not.toBeNull();
      expect(Number(m![1])).toBeLessThanOrEqual(total);
      // ערבית אשכנז: קטע 3 утверждён 06.10 (необратимо) → N ≥ 1.
      if (prayer === 'ערבית' && NUSACH[i] === 'אשכנז') expect(Number(m![1]), 'ערבית אשכנז: утверждённых ≥ 1').toBeGreaterThanOrEqual(1);
    }
    expect(body).toMatch(/אבינו מלכנו\s*.\s*נוסח אשכנז\s*\n+\s*\d+ מתוך \d+ קטעים מאושרים/);
  });
});
